def choose_move(observation):
    def g(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def is_num(x):
        return isinstance(x, (int, float))

    def pos_like(v):
        return (
            isinstance(v, (list, tuple)) and
            len(v) >= 2 and
            is_num(v[0]) and is_num(v[1])
        )

    def to_pos(v):
        if pos_like(v):
            return (int(v[0]), int(v[1]))
        return None

    def find_pos(obs):
        keys = ("position", "pos", "agent_pos", "self_pos", "location", "loc", "xy")
        for k in keys:
            p = to_pos(g(obs, k))
            if p is not None:
                return p
        for k in ("agent", "self", "me", "player"):
            sub = g(obs, k)
            if isinstance(sub, dict):
                for kk in keys:
                    p = to_pos(g(sub, kk))
                    if p is not None:
                        return p
        for k in ("agents", "players"):
            arr = g(obs, k, [])
            if isinstance(arr, list):
                for it in arr:
                    if isinstance(it, dict):
                        for kk in ("is_self", "self", "me", "controlled", "mine"):
                            if g(it, kk):
                                for pk in keys:
                                    p = to_pos(g(it, pk))
                                    if p is not None:
                                        return p
                        p = to_pos(it)
                        if p is not None:
                            return p
        return (0, 0)

    def collect_positions(val, out):
        if val is None:
            return
        if pos_like(val):
            out.append((int(val[0]), int(val[1])))
            return
        if isinstance(val, dict):
            p = None
            for kk in ("position", "pos", "location", "loc", "xy", "x_y"):
                p = to_pos(g(val, kk))
                if p is not None:
                    out.append(p)
            for vv in val.values():
                collect_positions(vv, out)
        elif isinstance(val, list):
            for it in val:
                collect_positions(it, out)

    def get_grid(obs):
        for k in ("grid", "board", "map", "terrain", "cells", "world"):
            v = g(obs, k)
            if isinstance(v, list) and v:
                return v
        return None

    def grid_dims(grid):
        h = len(grid)
        w = 0
        for row in grid:
            try:
                w = max(w, len(row))
            except Exception:
                pass
        return w, h

    def in_bounds(p, w, h):
        return 0 <= p[0] < w and 0 <= p[1] < h

    def cell(grid, x, y):
        try:
            return grid[y][x]
        except Exception:
            return None

    def blocked(v):
        if v is None:
            return True
        if v in (1, "#", "X", "x", "W", "w", "wall", "Wall", "obstacle", "Obstacle"):
            return True
        if isinstance(v, str):
            s = v.lower()
            if "wall" in s or "block" in s or "obst" in s:
                return True
        return False

    me = find_pos(observation)
    grid = get_grid(observation)
    w = h = 0
    if grid is not None:
        w, h = grid_dims(grid)

    attractive = []
    dangerous = []
    neutral_targets = []

    for k in ("resources", "resource", "food", "coins", "targets", "target", "goals", "goal",
              "enemies", "enemy", "opponents", "opponent", "enemy_positions",
              "territory", "territories", "frontier", "capture_points", "points"):
        v = g(observation, k)
        if v is not None:
            if k in ("enemies", "enemy", "opponents", "opponent", "enemy_positions"):
                collect_positions(v, dangerous)
            elif k in ("territory", "territories", "frontier", "capture_points", "points"):
                collect_positions(v, neutral_targets)
            else:
                collect_positions(v, attractive)

    # Also scan common nested containers
    for k in ("objects", "entities", "items", "units"):
        collect_positions(g(observation, k), attractive)
    for k in ("hazards", "traps", "threats"):
        collect_positions(g(observation, k), dangerous)

    # If no explicit targets, inspect grid for useful cells
    if grid is not None and not attractive:
        for y, row in enumerate(grid):
            try:
                ln = len(row)
            except Exception:
                continue
            for x in range(ln):
                v = row[x]
                if isinstance(v, (int, float)) and v > 0:
                    attractive.append((x, y))
                elif isinstance(v, str):
                    s = v.lower()
                    if any(t in s for t in ("resource", "food", "coin", "goal", "target", "capture")):
                        attractive.append((x, y))

    # Candidate moves
    moves = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            moves.append((dx, dy))

    best = (0, 0)
    best_score = -10**18

    # Determine step preference from task hints
    task = str(g(observation, "task", g(observation, "mode", g(observation, "game", "")))).lower()

    for dx, dy in moves:
        nx, ny = me[0] + dx, me[1] + dy
        score = 0

        if grid is not None:
            if not in_bounds((nx, ny), w, h):
                score -= 10_000
            else:
                v = cell(grid, nx, ny)
                if blocked(v):
                    score -= 10_000
                else:
                    if isinstance(v, (int, float)):
                        if v > 0:
                            score += 50 + int(v * 10)
                        elif v < 0:
                            score -= 25 + int(-v * 5)
                    elif isinstance(v, str):
                        s = v.lower()
                        if any(t in s for t in ("resource", "food", "coin", "goal", "target", "capture")):
                            score += 40
                        if any(t in s for t in ("enemy", "hazard", "trap", "wall", "block")):
                            score -= 40

        # Primary attraction: nearest useful target
        if attractive:
            dmin = 10**9
            for tx, ty in attractive:
                d = abs(tx - nx) + abs(ty - ny)
                if d < dmin:
                    dmin = d
            score += max(0, 30 - 3 * dmin)

        # Territory control: bias toward neutral targets and center if no targets
        if "territory" in task or "control" in task:
            if neutral_targets:
                dmin = 10**9
                for tx, ty in neutral_targets:
                    d = abs(tx - nx) + abs(ty - ny)
                    if d < dmin:
                        dmin = d
                score += max(0, 25 - 2 * dmin)
            elif grid is not None and w and h:
                cx, cy = w // 2, h // 2
                score += max(0, 8 - (abs(nx - cx) + abs(ny - cy)))

        # Pursuit/evasion: avoid danger, but if task suggests pursuit and no resources, close in
        if dangerous:
            dmin = 10**9
            for tx, ty in dangerous:
                d = abs(tx - nx) + abs(ty - ny)
                if d < dmin:
                    dmin = d
            score -= max(0, 20 - 2 * dmin)
            if "evasion" in task or "avoid" in task or "survival" in task:
                score += max(0, 12 - 2 * dmin)
            elif "pursuit" in task or "hunt" in task or "chase" in task:
                score += max(0, 10 - dmin)

        # Mild preference for movement over staying still when nothing else
        if dx == 0 and dy == 0:
            score -= 1

        # Small tie-break bias to deterministic, non-stationary motion
        score += (dx + 2 * dy)

        if score > best_score:
            best_score = score
            best = (dx, dy)

    return [best[0], best[1]]

